\[\frac{AQ^2 + AR^ 2+ BP^2 + BR^2 + CP^2 + CQ^2}{AB^2 + AC^2 + BC^2} = \frac{(1/2)^2(a^2 + b^2) + (1/2)^2(b^2 + c^2) + (1/2)^2(c^2 + a^2) + (1/2)^2(b^2 + c^2) + (1/2)^2(c^2 + a^2) + (1/2)^2(a^2 + c^2)}{c^2 + b^2 + a^2}
\\ = \frac{(1/4)(2a^2 + 2b^2 + 2c^2)}{c^2 + b^2 + a^2} = \frac{(1/2)(a^2 + b^2 + c^2)}{c^2 + b^2 + a^2} = \boxed{\frac{2}{3}}\]

